"use client";

import { useState, type FormEvent } from "react";
import Image from "next/image";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { Leaf, Loader2, ArrowLeft, ArrowRight, User, Lock, Mail, MapPin, Eye, EyeOff } from "lucide-react";
import { createClient } from "@/lib/supabase/client";

// Supabase Auth accounts are keyed by email. To support a plain username +
// password experience, accounts created without a real email get a
// synthetic one (`username@users.smart-waste.local`) — invisible to the
// user, never emailed to, just satisfies Supabase Auth's schema. The real
// username lives in `profiles.username` and is what's shown everywhere.
const SYNTHETIC_EMAIL_DOMAIN = "users.smart-waste.local";

export default function CitizenRegisterPage() {
  const router = useRouter();

  const [name, setName] = useState("");
  const [username, setUsername] = useState("");
  const [email, setEmail] = useState("");
  const [locality, setLocality] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const canSubmit = username.trim().length >= 3 && password.length >= 6;

  async function submit(e: FormEvent) {
    e.preventDefault();
    if (!canSubmit) return;
    setError(null);
    setLoading(true);

    const supabase = createClient();
    const normalizedUsername = username.trim().toLowerCase();
    const authEmail = email.trim() || `${normalizedUsername}@${SYNTHETIC_EMAIL_DOMAIN}`;

    const { error: signUpError } = await supabase.auth.signUp({
      email: authEmail,
      password,
      options: {
        data: {
          username: normalizedUsername,
          full_name: name.trim() || normalizedUsername,
          // Read by handle_new_user() in 0002_scan_identity.sql and written
          // to profiles.locality, which is what the operator's scan card shows.
          locality: locality.trim(),
        },
      },
    });

    if (signUpError) {
      setError(
        signUpError.message.includes("already registered")
          ? "That username or email is already registered."
          : signUpError.message
      );
      setLoading(false);
      return;
    }

    router.push("/citizen");
    router.refresh();
  }

  return (
    <div className="relative flex min-h-screen flex-col items-center justify-center overflow-hidden bg-slate-950 px-6 py-12">
      <Image src="/login-bg.jpg" alt="" fill priority className="object-cover" />
      <div className="absolute inset-0 bg-gradient-to-b from-slate-950/80 via-slate-950/55 to-slate-950/85" />
      <div className="absolute inset-0 bg-gradient-to-tr from-brand-primary-dark/40 via-transparent to-transparent" />

      <Link
        href="/citizen-login"
        className="relative z-10 mb-6 flex items-center gap-1.5 self-start text-xs font-medium text-white/70 hover:text-white"
      >
        <ArrowLeft className="h-3.5 w-3.5" /> Back to sign in
      </Link>

      <div className="relative z-10 mb-6 flex flex-col items-center gap-2 text-center">
        <div className="flex h-14 w-14 items-center justify-center rounded-2xl bg-white/10 text-white shadow-xl ring-1 ring-white/25 backdrop-blur-sm">
          <Leaf className="h-7 w-7" />
        </div>
        <p className="text-lg font-semibold text-white">Swachh Saathi</p>
        <p className="text-xs text-white/60">Create your citizen account</p>
      </div>

      <div className="relative z-10 w-full max-w-sm rounded-3xl border border-white/20 bg-white/10 p-6 shadow-2xl shadow-black/40 backdrop-blur-xl">
        <form onSubmit={submit} className="space-y-3.5">
          <div>
            <label className="mb-1.5 block text-xs font-medium text-white/80">Your name</label>
            <div className="relative">
              <User className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-white/50" />
              <input
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="e.g. Priya Sharma"
                autoComplete="name"
                className="w-full rounded-xl border border-white/25 bg-white/10 py-2.5 pl-10 pr-3 text-sm text-white placeholder:text-white/40 outline-none transition focus:border-white/60 focus:bg-white/15"
              />
            </div>
          </div>
          <div>
            <label className="mb-1.5 block text-xs font-medium text-white/80">Username</label>
            <div className="relative">
              <User className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-white/50" />
              <input
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                placeholder="pick a username"
                autoComplete="username"
                className="w-full rounded-xl border border-white/25 bg-white/10 py-2.5 pl-10 pr-3 text-sm text-white placeholder:text-white/40 outline-none transition focus:border-white/60 focus:bg-white/15"
              />
            </div>
          </div>
          <div>
            <label className="mb-1.5 block text-xs font-medium text-white/80">
              Email <span className="text-white/40">(optional)</span>
            </label>
            <div className="relative">
              <Mail className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-white/50" />
              <input
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                type="email"
                placeholder="you@example.com"
                autoComplete="email"
                className="w-full rounded-xl border border-white/25 bg-white/10 py-2.5 pl-10 pr-3 text-sm text-white placeholder:text-white/40 outline-none transition focus:border-white/60 focus:bg-white/15"
              />
            </div>
          </div>
          <div>
            <label className="mb-1.5 block text-xs font-medium text-white/80">
              Locality / Ward <span className="text-white/40">(optional)</span>
            </label>
            <div className="relative">
              <MapPin className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-white/50" />
              <input
                value={locality}
                onChange={(e) => setLocality(e.target.value)}
                placeholder="e.g. Indore, Ward 12"
                className="w-full rounded-xl border border-white/25 bg-white/10 py-2.5 pl-10 pr-3 text-sm text-white placeholder:text-white/40 outline-none transition focus:border-white/60 focus:bg-white/15"
              />
            </div>
          </div>
          <div>
            <label className="mb-1.5 block text-xs font-medium text-white/80">Password</label>
            <div className="relative">
              <Lock className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-white/50" />
              <input
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                type={showPassword ? "text" : "password"}
                placeholder="At least 6 characters"
                autoComplete="new-password"
                className="w-full rounded-xl border border-white/25 bg-white/10 py-2.5 pl-10 pr-10 text-sm text-white placeholder:text-white/40 outline-none transition focus:border-white/60 focus:bg-white/15"
              />
              <button
                type="button"
                onClick={() => setShowPassword((s) => !s)}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-white/50 hover:text-white/80"
                aria-label={showPassword ? "Hide password" : "Show password"}
              >
                {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
              </button>
            </div>
          </div>

          {error && <p className="text-xs font-medium text-red-300">{error}</p>}

          <button
            type="submit"
            disabled={!canSubmit || loading}
            className="flex w-full items-center justify-center gap-2 rounded-xl bg-brand-primary py-2.5 text-sm font-semibold text-white shadow-lg shadow-brand-primary/30 transition hover:bg-emerald-600 disabled:cursor-not-allowed disabled:opacity-50"
          >
            {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : (
              <>Create account <ArrowRight className="h-4 w-4" /></>
            )}
          </button>
        </form>
      </div>
    </div>
  );
}
